import React, { useState } from 'react';

function VulnCard({ finding, index }) {
  const [open, setOpen] = useState(false);

  const badgeClass =
    finding.severity === 'High'
      ? 'badge-high'
      : finding.severity === 'Medium'
      ? 'badge-medium'
      : 'badge-low';

  return (
    <div className="vuln-card">
      <div className="vuln-header" onClick={() => setOpen(!open)}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
          <span style={{ color: 'var(--text-muted)', fontSize: '0.8rem', fontFamily: 'Share Tech Mono, monospace' }}>
            #{String(index + 1).padStart(2, '0')}
          </span>
          {finding.lineNumber && (
            <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)', background: 'var(--bg-secondary)', padding: '0.1rem 0.4rem', borderRadius: '4px', fontFamily: 'Share Tech Mono, monospace' }}>
              line {finding.lineNumber}
            </span>
          )}
          <h3>{finding.name}</h3>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
          <span className={`badge ${badgeClass}`}>{finding.severity}</span>
          <span style={{ color: 'var(--text-muted)', fontSize: '1rem' }}>{open ? '▲' : '▼'}</span>
        </div>
      </div>

      {open && (
        <div className="vuln-body">
          <div className="vuln-section">
            <div className="vuln-section-label">Description</div>
            <p>{finding.description}</p>
          </div>
          <div className="vuln-section">
            <div className="vuln-section-label">Impact</div>
            <p>{finding.impact}</p>
          </div>
          <div className="vuln-section">
            <div className="vuln-section-label">Recommendation</div>
            <p style={{ color: 'var(--low)' }}>{finding.recommendation}</p>
          </div>
          <div className="vuln-section">
            <div className="vuln-section-label">Secure Code Example</div>
            <pre className="code-block">{finding.secureExample}</pre>
          </div>
        </div>
      )}
    </div>
  );
}

export default VulnCard;
