import React from 'react';
import { Doughnut } from 'react-chartjs-2';
import { Chart as ChartJS, ArcElement, Tooltip, Legend } from 'chart.js';

ChartJS.register(ArcElement, Tooltip, Legend);

function SeverityChart({ high, medium, low }) {
  const total = high + medium + low;

  if (total === 0) {
    return (
      <div style={{ textAlign: 'center', padding: '2rem', color: 'var(--low)' }}>
        <div style={{ fontSize: '2.5rem', marginBottom: '0.5rem' }}>✓</div>
        <div style={{ fontSize: '0.875rem' }}>No vulnerabilities found</div>
      </div>
    );
  }

  const data = {
    labels: ['High', 'Medium', 'Low'],
    datasets: [
      {
        data: [high, medium, low],
        backgroundColor: ['rgba(255,71,87,0.85)', 'rgba(255,165,2,0.85)', 'rgba(46,213,115,0.85)'],
        borderColor: ['#ff4757', '#ffa502', '#2ed573'],
        borderWidth: 1,
      },
    ],
  };

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'bottom',
        labels: {
          color: '#7bafc8',
          padding: 16,
          font: { size: 12 },
        },
      },
    },
    cutout: '65%',
  };

  return (
    <div style={{ height: '220px', position: 'relative' }}>
      <Doughnut data={data} options={options} />
    </div>
  );
}

export default SeverityChart;
